# helper
def slide_right(g):
 R,C=len(g),len(g[0]); unseen={(r,c) for r in range(R) for c in range(C) if g[r][c]}; objs=[]
 while unseen:
  p=unseen.pop(); color=g[p[0]][p[1]]; comp={p}; stack=[p]
  while stack:
   r,c=stack.pop()
   for q in [(r+1,c),(r-1,c),(r,c+1),(r,c-1)]:
    if q in unseen and g[q[0]][q[1]]==color:
     unseen.remove(q);comp.add(q);stack.append(q)
  objs.append((color,comp))
 bs=[set(b) for co,b in objs]
 for _ in range(C):
  occ={p:i for i,b in enumerate(bs) for p in b}; movable=set(range(len(bs)))
  for i,b in enumerate(bs):
   if any(c+1>=C for r,c in b): movable.discard(i)
  changed=True
  while changed:
   changed=False
   for i in list(movable):
    if any((r,c+1) in occ and occ[(r,c+1)] not in movable for r,c in bs[i]): movable.remove(i);changed=True
  if not movable:break
  bs=[{(r,c+1) if i in movable else (r,c) for r,c in b} for i,b in enumerate(bs)]
 out=[[0]*C for _ in range(R)]
 for (co,_),b in zip(objs,bs):
  for r,c in b:out[r][c]=co
 return out
